// Constant-load hinge equilibrium with analytically prescribed angle and anchor vector.
// Four fixed cases, original60Hz/damping2; tail120of600 thresholds frozen in protocol.
#include "box3d/box3d.h"
#include <cmath>
#include <cstdio>
#include <initializer_list>
