static double norm(b3Vec3 a){return std::sqrt(double(a.x)*a.x+double(a.y)*a.y+double(a.z)*a.z);}
int main(){bool pass=true;int caseId=0;
 for(float lever:{0.0f,0.4f})for(float angle:{0.01f,0.1f}){
  auto wd=b3DefaultWorldDef();wd.gravity={0,0,0};wd.enableSleep=false;auto world=b3CreateWorld(&wd);
  auto bd=b3DefaultBodyDef();auto ground=b3CreateBody(world,&bd);
  const float h=1.0f/240.0f;double hz=std::fmin(60.0,0.25/double(h));double omega2=std::pow(2*3.14159265358979323846*hz,2);
